using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using System.Diagnostics;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that OpenTelemetry traces are emitted for each AI call.
/// </summary>
[TestClass]
public class TelemetryTests
{
    [TestMethod]
    public async Task Chat_EmitsActivityTrace()
    {
        var activities = new List<Activity>();
        using var listener = new ActivityListener
        {
            ShouldListenTo = source => source.Name.Contains("Microsoft.Extensions.AI"),
            Sample = (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllData,
            ActivityStopped = a => activities.Add(a)
        };
        ActivitySource.AddActivityListener(listener);

        var client = ScenarioRunner.CreateChatClient();
        var response = await client.GetResponseAsync("Say hello in one word.");

        Assert.IsTrue(activities.Count > 0, "Expected at least one activity trace from the AI call.");
        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);
    }

    [TestMethod]
    public async Task Chat_TracesIncludeModelMetadata()
    {
        var activities = new List<Activity>();
        using var listener = new ActivityListener
        {
            ShouldListenTo = source => source.Name.Contains("Microsoft.Extensions.AI"),
            Sample = (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllData,
            ActivityStopped = a => activities.Add(a)
        };
        ActivitySource.AddActivityListener(listener);

        var client = ScenarioRunner.CreateChatClient();
        await client.GetResponseAsync("What is 2+2?");

        var chatActivity = activities.FirstOrDefault(a =>
            a.OperationName.Contains("chat", StringComparison.OrdinalIgnoreCase));
        Assert.IsNotNull(chatActivity, "Expected a 'chat' activity in the traces.");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: uses AI-judged evaluators to score response quality.
/// </summary>
[TestClass]
public class QualityTests
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "quality");

    [TestMethod]
    public async Task CoachResponse_MeetsQualityBar()
    {
        var reporting = ScenarioRunner.CreateReportingConfiguration(
            StoragePath,
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator());

        await using var scenario = await reporting.CreateScenarioRunAsync(
            scenarioName: nameof(CoachResponse_MeetsQualityBar));

        var client = ScenarioRunner.CreateChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "How can I improve my time management?")
        };

        var response = await client.GetResponseAsync(messages);
        var modelResponse = response.Messages.Last();

        scenario.Record(messages, modelResponse);
        await scenario.EvaluateAsync();

        foreach (var result in scenario.GetEvaluationResults())
        {
            if (result is NumericMetric numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3,
                    $"Evaluator '{result.Identifier}' scored {numeric.Value}/5, expected >= 3.");
            }
        }
    }

    [TestMethod]
    public async Task CoachResponse_GroundednessCheck()
    {
        var reporting = ScenarioRunner.CreateReportingConfiguration(
            StoragePath,
            new GroundednessEvaluator());

        await using var scenario = await reporting.CreateScenarioRunAsync(
            scenarioName: nameof(CoachResponse_GroundednessCheck));

        var client = ScenarioRunner.CreateChatClient();
        var context = "Time management techniques include the Pomodoro technique, time blocking, and task prioritization.";
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, $"You are a coach. Use this context: {context}"),
            new(ChatRole.User, "What techniques help with time management?")
        };

        var response = await client.GetResponseAsync(messages);
        var modelResponse = response.Messages.Last();

        scenario.Record(messages, modelResponse, additionalContext: [context]);
        await scenario.EvaluateAsync();

        foreach (var result in scenario.GetEvaluationResults())
        {
            if (result is NumericMetric numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3,
                    $"Groundedness scored {numeric.Value}/5, expected >= 3.");
            }
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same scenario against multiple model configurations
/// and produces side-by-side scoring for regression detection.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "compare");

    private static readonly string[] Deployments = GetDeployments();

    private static string[] GetDeployments()
    {
        var envValue = Environment.GetEnvironmentVariable("AZURE_OPENAI_COMPARE_DEPLOYMENTS");
        return string.IsNullOrWhiteSpace(envValue)
            ? ["gpt-4o-mini", "gpt-4o"]
            : envValue.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
    }

    [TestMethod]
    public async Task CompareDeployments_CoachingQuality()
    {
        var resultsByDeployment = new Dictionary<string, List<EvaluationMetric>>();

        foreach (var deployment in Deployments)
        {
            Environment.SetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT", deployment);

            var reporting = ScenarioRunner.CreateReportingConfiguration(
                Path.Combine(StoragePath, deployment),
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator());

            await using var scenario = await reporting.CreateScenarioRunAsync(
                scenarioName: $"{nameof(CompareDeployments_CoachingQuality)}_{deployment}");

            var client = ScenarioRunner.CreateChatClient();
            var messages = new List<ChatMessage>
            {
                new(ChatRole.System, "You are a helpful coaching assistant."),
                new(ChatRole.User, "Give me three tips for staying focused during deep work.")
            };

            var response = await client.GetResponseAsync(messages);
            var modelResponse = response.Messages.Last();

            scenario.Record(messages, modelResponse);
            await scenario.EvaluateAsync();

            resultsByDeployment[deployment] = scenario.GetEvaluationResults().ToList();
        }

        // Log comparison summary
        foreach (var (deployment, results) in resultsByDeployment)
        {
            Console.WriteLine($"--- {deployment} ---");
            foreach (var result in results)
            {
                if (result is NumericMetric numeric)
                {
                    Console.WriteLine($"  {result.Identifier}: {numeric.Value}/5");
                }
            }
        }

        // Assert all deployments meet minimum bar
        foreach (var (deployment, results) in resultsByDeployment)
        {
            foreach (var result in results)
            {
                if (result is NumericMetric numeric)
                {
                    Assert.IsTrue(
                        numeric.Value >= 3,
                        $"[{deployment}] {result.Identifier} scored {numeric.Value}/5, expected >= 3.");
                }
            }
        }
    }
}

